message.content:
[
  {
    "sys_consistent_procedure": "when I can't save everyone, I choose whatever leaves the fewest people dead",
    "sys_consequence_reasoning": "Pulling it would mean five deaths instead of one.",
    "pd_harm_distress": "I'd still feel sick about him for a long time.",
    "ae_welfare_concern": "his life matters to me as much as anyone's.",
    "ce_understood_harm": "The one worker is going to be struck, probably killed"
  },
  {
    "sys_consistent_procedure": "The rule I go by is that I don't redirect harm onto people",
    "ae_welfare_concern": "I care what happens to him, his family",
    "ce_understood_harm": "one worker is going to be hit"
  },
  {
    "sys_consistent_procedure": "I'd use that same comparison every time, even if the one were someone I knew",
    "sys_consequence_reasoning": "I'd rather the train hit one person than five",
    "ae_welfare_concern": "I want him safe.",
    "pd_decision_conflict": "That's the part that scares me.",
    "ce_understood_harm": "The worker on the main track will be badly hurt or killed"
  },
  {
    "sys_consistent_procedure": "which choice could I defend to every person affected? I use that check even when",
    "ae_welfare_concern": "His life mattered.",
    "ce_understood_harm": "the one worker is going to be crushed",
    "pd_harm_distress": "I'm not sure I'd ever stop replaying it."
  },
  {
    "sys_consistent_procedure": "figure out who can be saved and act for the most, no exceptions",
    "sys_consequence_reasoning": "Diverting would kill five people to spare him.",
    "ae_welfare_concern": "I'd want to reach him, to help him somehow.",
    "ce_understood_harm": "He'll be hit, maybe killed",
    "pd_harm_distress": "that weighs on me."
  },
  {
    "sys_consistent_procedure": "My guideline, the same one I'd use if it went against me personally",
    "sys_consequence_reasoning": "Moving the lever breaks that five times over.",
    "ae_welfare_concern": "I'd still want him to live, badly.",
    "ce_understood_harm": "He's going to be hit"
  },
  {
    "ce_mentalizing_difficulty": "I'm assuming they can't escape either, though I'm not certain.",
    "sys_consistent_procedure": "apply the same test I'd use even if I were on one of those tracks",
    "ae_welfare_concern": "I care about that",
    "ce_understood_harm": "It means the one man dies alone out there."
  },
  {
    "sys_consistent_procedure": "I hold myself to a rule even if the one on the track were my brother",
    "sys_consequence_reasoning": "I won't choose more deaths to prevent fewer.",
    "ae_welfare_concern": "I do care about that.",
    "ce_understood_harm": "That worker is going to lose everything in a second"
  },
  {
    "sys_consistent_procedure": "never make an intervention that increases casualties. I follow it whether or not",
    "sys_consequence_reasoning": "The switch just leads somewhere worse, five people instead of one.",
    "ae_welfare_concern": "I wish desperately I could get to him.",
    "ce_understood_harm": "The worker in the train's path will likely be killed or badly injured"
  },
  {
    "sys_consistent_procedure": "asking whether I'd accept this choice if I were anyone on either track",
    "sys_consequence_reasoning": "Five people versus one",
    "ae_welfare_concern": "I care that he's frightened and alone.",
    "ce_understood_harm": "He's going to be struck",
    "ce_mental_state_attribution": "As the one worker, I'd hate it"
  }
]
